#!/usr/bin/env bash
# Option 1: FHS environment -> Bubblewrap environment
# Option 2: Bubblewrap environemnt -> FHS environment (is ths possible?)
#
# Option 1 Layers
# - Nix realized derivation for FHS environment in Nix store (i.e. a GNU Bash script that runs an 
#   interactive Bash session with file system directories and environment variables set)

set -e

# Path to the FHS environment generated by Nix
# TODO: not quite right
FHS_PATH=$(nix-build -E '(builtins.elemAt (import ./shell.nix {}).buildInputs 1)')

echo "The FHS path is: $FHS_PATH"

# Prepare clean workspace directories
mkdir -p ./bwrap-root/tmp ./bwrap-root/home ./bwrap-root/var/lib/containers

bwrap \
  --ro-bind "$FHS_PATH/bin" /bin \
  --ro-bind "$FHS_PATH/lib" /lib \
  --ro-bind "$FHS_PATH/lib64" /lib64 \
  --ro-bind "$FHS_PATH/usr" /usr \
  --dir /dev \
  --dev /dev \
  --proc /proc \
  --tmpfs /sys \
  --tmpfs /tmp \
  --tmpfs /run \
  --dir /var/lib/containers \
  --bind ./bwrap-root/var/lib/containers /var/lib/containers \
  --bind ./bwrap-root/home /home/agent \
  --setenv HOME /home/agent \
  --unshare-user \
  --unshare-pid \
  --unshare-uts \
  --share-net \
  --ro-bind /etc/resolv.conf /etc/resolv.conf \
  --ro-bind /etc/k3s/k3s.yaml /home/agent/.kube/config \
  --setenv KUBECONFIG /home/agent/.kube/config \
  /bin/bash
